import React from 'react';
import logo from './logo.svg';
import './App.css';
import { Route, Routes } from 'react-router-dom';
import Layout from './Layout/Layout';
import Home from './Pages/Home';
import ProfileCard from './Pages/Profile';
import LoginPage from './Pages/Login/Login';
import { UserProvider } from './Context/userContext';
import TopBar from './Component/TopBar';
import { ThemeProvider } from '@emotion/react';
import theme from './theme';
import LoanScreen from './Pages/LoanScreen';
const token = localStorage.getItem('token');
function App() {
  return (

    <ThemeProvider theme={theme}>
      <div className="App">
        {/* <TopBar /> */}
        <div style={{ marginTop: 0 }}>
          {token ? (<UserProvider><Layout ><Routes>
            <Route path="/" element={<Home />}></Route>
            <Route path="profile" element={<ProfileCard />}></Route>
            <Route path="loan" element={<LoanScreen />}></Route>
          </Routes></Layout></UserProvider>) : (<Routes><Route path='*' element={<LoginPage />}></Route></Routes>)}
        </div>
      </div>
    </ThemeProvider>
  );
}

export default App;
